<template><GameLayout><div v-if="partida" class="game-view"><div class="turn-banner"><span>RODADA {{ partida.rodada }}</span><strong>{{ partida.jogadores[partida.jogadorAtual].nome }} joga agora</strong></div><div class="table-center"><p class="kicker">SUA MÃO</p><div class="cards"><button v-for="carta in suaMao" :key="carta.id" class="card" @click="passar(carta.id)"><small>{{ carta.naipe }}</small><strong>{{ carta.valor }}</strong><span>passar →</span></button></div><p class="hint">Toque em uma carta para passar ao próximo jogador.</p></div><div class="players-row"><div v-for="jogador in partida.jogadores" :key="jogador.id" class="player-chip" :class="{ active: jogador.ordem === partida.jogadorAtual }"><span>{{ jogador.nome[0] }}</span><strong>{{ jogador.nome }}</strong><small>{{ jogador.mao.length }} cartas · {{ 'B'.repeat(jogador.letrasBurro) || 'sem letras' }}</small></div></div><ion-button fill="clear" color="danger" @click="encerrar">Sair da partida</ion-button></div><p v-else>Crie uma partida para começar.</p></GameLayout></template>
<script setup lang="ts">import { computed } from 'vue'; import { useRouter } from 'vue-router'; import { IonButton } from '@ionic/vue'; import GameLayout from '@/components/GameLayout.vue'; import { gameStore } from '@/stores/game'; const router = useRouter(); const partida = computed(() => gameStore.estado.partida); const suaMao = computed(() => partida.value?.jogadores[0].mao || []); function passar(id: string) { if (partida.value?.jogadorAtual === 0) gameStore.jogar(id); } function encerrar() { gameStore.encerrar('cancelada'); router.push('/resultado'); }</script>
